-- Refer to https://wiki.hypr.land/Configuring/Basics/Variables/
hl.config({
	general = {
		gaps_in = 5,
		gaps_out = 20,

		border_size = 2,

		col = {
			-- Glassmorphism: un solo blanco puro (#ffffff) en todo el borde; lo
			-- que cambia a lo largo del gradiente es el alfa, no el tono. El
			-- borde arranca casi opaco en la esquina superior izquierda y se
			-- desvanece hacia la inferior derecha, que es como el cristal
			-- esmerilado recoge la luz: un filo brillante que se apaga.
			active_border = { colors = { "rgba(ffffffe6)", "rgba(ffffff26)" }, angle = 45 },
			-- La ventana inactiva conserva el filo, pero apenas insinuado.
			inactive_border = "rgba(ffffff1a)",
		},

		-- Set to true to enable resizing windows by clicking and dragging on borders and gaps
		resize_on_border = false,

		-- Please see https://wiki.hypr.land/Configuring/Advanced-and-Cool/Tearing/ before you turn this on
		allow_tearing = false,

		layout = "dwindle",
	},

	decoration = {
		rounding = 10,
		rounding_power = 2,

		-- Change transparency of focused and unfocused windows
		active_opacity = 1.0,
		inactive_opacity = 1.0,

		shadow = {
			enabled = true,
			range = 4,
			render_power = 3,
			color = 0xee1a1a1a,
		},

		blur = {
			enabled = true,
			size = 8,
			passes = 3,
			vibrancy = 0.25,
			noise = 0.02, -- frosted-glass grain
			new_optimizations = true,
		},
	},

	animations = {
		enabled = true,
	},
})

-- Default curves and animations, see https://wiki.hypr.land/Configuring/Advanced-and-Cool/Animations/
hl.curve("easeOutQuint", { type = "bezier", points = { { 0.23, 1 }, { 0.32, 1 } } })
hl.curve("easeInOutCubic", { type = "bezier", points = { { 0.65, 0.05 }, { 0.36, 1 } } })
hl.curve("linear", { type = "bezier", points = { { 0, 0 }, { 1, 1 } } })
hl.curve("almostLinear", { type = "bezier", points = { { 0.5, 0.5 }, { 0.75, 1 } } })
hl.curve("quick", { type = "bezier", points = { { 0.15, 0 }, { 0.1, 1 } } })

-- Default springs
hl.curve("easy", { type = "spring", mass = 1, stiffness = 238.1191, dampening = 24.21279333 })

-- Underdamped spring (damping ratio ~0.57): one clear bounce, then it settles
-- instead of oscillating the way stiffness=140/dampening=9 did.
hl.curve("bounce", { type = "spring", mass = 1, stiffness = 170, dampening = 15 })

-- Same idea as "bounce" but barely there: damping ratio ~0.67 overshoots the
-- resting position by about 5% and settles on the first swing back, so a layer
-- coming in gets the launcher's rebound without the visible wobble.
hl.curve("subtleBounce", { type = "spring", mass = 1, stiffness = 200, dampening = 19 })

-- Smooth, monotone exit: no spring, so nothing overshoots on the way out.
hl.curve("easeInOutQuint", { type = "bezier", points = { { 0.83, 0 }, { 0.17, 1 } } })

hl.animation({ leaf = "global", enabled = true, speed = 10, bezier = "default" })
hl.animation({ leaf = "border", enabled = true, speed = 5.39, bezier = "easeOutQuint" })
hl.animation({ leaf = "windows", enabled = true, speed = 4.79, spring = "easy" })
hl.animation({ leaf = "windowsIn", enabled = true, speed = 4.1, spring = "easy", style = "popin 87%" })
hl.animation({ leaf = "windowsOut", enabled = true, speed = 1.49, bezier = "linear", style = "popin 87%" })
hl.animation({ leaf = "fadeIn", enabled = true, speed = 1.73, bezier = "almostLinear" })
hl.animation({ leaf = "fadeOut", enabled = true, speed = 1.46, bezier = "almostLinear" })
hl.animation({ leaf = "fade", enabled = true, speed = 3.03, bezier = "quick" })
hl.animation({ leaf = "layers", enabled = true, speed = 3.81, bezier = "easeOutQuint" })
-- The style is set per-namespace via layer_rule, since Hyprland only allows a
-- fixed set of animation leaves. Avoid "popin" on layer surfaces: it animates
-- the geometry box from the top-left, so the right/bottom edges visibly step
-- out as squares and the rounded corners get clipped.
-- In: springs past the resting edge and settles back (the subtle rebound).
-- Out: plain easing, so hiding reads as one smooth slide with no rebound at all.
hl.animation({ leaf = "layersIn", enabled = true, speed = 4.2, spring = "subtleBounce" })
hl.animation({ leaf = "layersOut", enabled = true, speed = 3, bezier = "easeInOutQuint" })
-- The fades are timed against the slides above: quick in (the spring is still
-- settling once the bar is fully opaque), and slow enough out that the bar does
-- not blink away before it has finished sliding off.
hl.animation({ leaf = "fadeLayersIn", enabled = true, speed = 1.79, bezier = "almostLinear" })
hl.animation({ leaf = "fadeLayersOut", enabled = true, speed = 2.5, bezier = "almostLinear" })
hl.animation({ leaf = "workspaces", enabled = true, speed = 1.94, bezier = "almostLinear", style = "fade" })
hl.animation({ leaf = "workspacesIn", enabled = true, speed = 1.21, bezier = "almostLinear", style = "fade" })
hl.animation({ leaf = "workspacesOut", enabled = true, speed = 1.94, bezier = "almostLinear", style = "fade" })
hl.animation({ leaf = "zoomFactor", enabled = true, speed = 7, bezier = "quick" })

