-- Ported from https://github.com/IshimiG/set-up (.config/hypr/bindings.conf),
-- which targets Omarchy. omarchy-launch-* / omarchy-cmd-* helpers don't exist
-- here, so they're replaced with the equivalent plain commands, and the
-- "launch or focus" ones use ~/.local/bin/launch-or-focus (matches an
-- existing window by class/title, or launches the app).

local focusOrLaunch = os.getenv("HOME") .. "/.local/bin/launch-or-focus"

hl.bind(mainMod .. " + RETURN", hl.dsp.exec_cmd(terminal))
hl.bind(mainMod .. " + ALT + RETURN", hl.dsp.exec_cmd(terminal .. " -e bash -c \"tmux attach || tmux new -s Work\""))
hl.bind(mainMod .. " + SHIFT + RETURN", hl.dsp.exec_cmd(browser))
hl.bind(mainMod .. " + SHIFT + B", hl.dsp.exec_cmd(browser))
hl.bind(mainMod .. " + SHIFT + ALT + B", hl.dsp.exec_cmd(browser .. " --private-window"))
hl.bind(mainMod .. " + SHIFT + F", hl.dsp.exec_cmd("nautilus --new-window"))
hl.bind(mainMod .. " + ALT + SHIFT + F", hl.dsp.exec_cmd("nautilus --new-window"))
hl.bind(mainMod .. " + SHIFT + M", hl.dsp.exec_cmd(focusOrLaunch .. " spotify spotify"))
hl.bind(mainMod .. " + SHIFT + ALT + M", hl.dsp.exec_cmd(focusOrLaunch .. " cliamp " .. terminal .. " --title=cliamp -e cliamp"))
hl.bind(mainMod .. " + SHIFT + N", hl.dsp.exec_cmd(terminal .. " -e nvim"))
hl.bind(mainMod .. " + SHIFT + D", hl.dsp.exec_cmd(focusOrLaunch .. " lazydocker " .. terminal .. " --title=lazydocker -e lazydocker"))
hl.bind(mainMod .. " + SHIFT + G", hl.dsp.exec_cmd(focusOrLaunch .. " signal signal-desktop"))
hl.bind(mainMod .. " + SHIFT + O", hl.dsp.exec_cmd(focusOrLaunch .. " obsidian obsidian"))
hl.bind(mainMod .. " + SHIFT + W", hl.dsp.exec_cmd("typora --enable-wayland-ime"))
hl.bind(mainMod .. " + SHIFT + SLASH", hl.dsp.exec_cmd("1password"))

-- Web apps. Antes se abrían con "chromium --app", que da una ventana sin
-- barra de navegación. Zen es Firefox y no tiene modo app, así que ahora van
-- con --new-window: misma web, pero en una ventana normal con su barra.
hl.bind(mainMod .. " + SHIFT + A", hl.dsp.exec_cmd(browser .. ' --new-window https://chatgpt.com'))
hl.bind(mainMod .. " + SHIFT + ALT + A", hl.dsp.exec_cmd(browser .. ' --new-window https://grok.com'))
hl.bind(mainMod .. " + SHIFT + C", hl.dsp.exec_cmd(browser .. ' --new-window https://app.hey.com/calendar/weeks/'))
hl.bind(mainMod .. " + SHIFT + E", hl.dsp.exec_cmd(browser .. ' --new-window https://app.hey.com'))
hl.bind(mainMod .. " + SHIFT + Y", hl.dsp.exec_cmd(browser .. ' --new-window https://youtube.com/'))
-- Sin --class: Firefox solo lo respeta en X11, y bajo Wayland el app_id lo
-- fija el .desktop, así que todas las ventanas de Zen comparten clase. El
-- launch-or-focus de estas dos pasa a depender del título de la ventana.
hl.bind(mainMod .. " + SHIFT + ALT + G", hl.dsp.exec_cmd(focusOrLaunch .. ' WhatsApp ' .. browser .. ' --new-window https://web.whatsapp.com/'))
hl.bind(mainMod .. " + SHIFT + CTRL + G", hl.dsp.exec_cmd(focusOrLaunch .. ' "Google Messages" ' .. browser .. ' --new-window https://messages.google.com/web/conversations'))
hl.bind(mainMod .. " + SHIFT + P", hl.dsp.exec_cmd(browser .. ' --new-window https://photos.google.com/'))
hl.bind(mainMod .. " + SHIFT + X", hl.dsp.exec_cmd(browser .. ' --new-window https://x.com/'))
hl.bind(mainMod .. " + SHIFT + ALT + X", hl.dsp.exec_cmd(browser .. ' --new-window https://x.com/compose/post'))

-- Toggle floating (moved here from SUPER + V)
hl.bind(mainMod .. " + T", hl.dsp.window.float({ action = "toggle" }))

-- Show/hide waybar. Waybar's own SIGUSR1 hide only sets the GTK window's
-- opacity to 0 and leaves the layer surface mapped, so Hyprland never sees it
-- appear or disappear and cannot animate it. Stopping and restarting the
-- process really destroys and re-creates the surface, which is what makes the
-- layersOut/layersIn animations above run. Waybar maps its surface again about
-- 90ms after launch, so the rebound starts essentially on keypress.
hl.bind(mainMod .. " + SHIFT + V", hl.dsp.exec_cmd("sh -c 'pkill -x waybar || waybar'"))

-- SUPER + C centers the window (close is now on SUPER + W above)
hl.bind(mainMod .. " + C", hl.dsp.window.center())

-- Redimensionar la ventana activa con los mismos controles que Omarchy
-- (default/hypr/bindings/tiling.lua): las dos teclas a la derecha del 0.
-- Omarchy las declara por keycode físico, pero el parser Lua de Hyprland
-- 0.56.2 no acepta esa sintaxis (no separa los modificadores de la tecla),
-- así que aquí van por keysym del teclado español:
--   apostrophe = la tecla ' (donde en QWERTY US está el "-")
--   exclamdown = la tecla ¡ (donde en QWERTY US está el "=", antes de Backspace)
-- SUPER solo = 100px, SUPER + ALT = 25px (fino), SUPER + CTRL = 300px (grueso).
-- Sin SHIFT se ajusta el ancho; con SHIFT, el alto.
local resizeSteps = {
	{ mods = "", step = 100 }, -- paso normal
	{ mods = " + ALT", step = 25 }, -- paso fino
	{ mods = " + CTRL", step = 300 }, -- paso grande
}

for _, resize in ipairs(resizeSteps) do
	-- Ancho: ' ensancha hacia la izquierda, ¡ estrecha.
	hl.bind(
		mainMod .. resize.mods .. " + apostrophe",
		hl.dsp.window.resize({ x = -resize.step, y = 0, relative = true }),
		{ repeating = true }
	)
	hl.bind(
		mainMod .. resize.mods .. " + exclamdown",
		hl.dsp.window.resize({ x = resize.step, y = 0, relative = true }),
		{ repeating = true }
	)

	-- Alto: con SHIFT, ' encoge hacia arriba y ¡ estira hacia abajo.
	hl.bind(
		mainMod .. resize.mods .. " + SHIFT + apostrophe",
		hl.dsp.window.resize({ x = 0, y = -resize.step, relative = true }),
		{ repeating = true }
	)
	hl.bind(
		mainMod .. resize.mods .. " + SHIFT + exclamdown",
		hl.dsp.window.resize({ x = 0, y = resize.step, relative = true }),
		{ repeating = true }
	)
end

