-- See https://wiki.hypr.land/Configuring/Basics/Window-Rules/
-- and https://wiki.hypr.land/Configuring/Basics/Workspace-Rules/

-- Example window rules that are useful

local suppressMaximizeRule = hl.window_rule({
	-- Ignore maximize requests from all apps. You'll probably like this.
	name = "suppress-maximize-events",
	match = { class = ".*" },

	suppress_event = "maximize",
})
-- suppressMaximizeRule:set_enabled(false)

hl.window_rule({
	-- Fix some dragging issues with XWayland
	name = "fix-xwayland-drags",
	match = {
		class = "^$",
		title = "^$",
		xwayland = true,
		float = true,
		fullscreen = false,
		pin = false,
	},

	no_focus = true,
})

-- Layer rules also return a handle.
-- local overlayLayerRule = hl.layer_rule({
--     name  = "no-anim-overlay",
--     match = { namespace = "^my-overlay$" },
--     no_anim = true,
-- })
-- overlayLayerRule:set_enabled(false)

-- Curve/speed come from the global layersIn/layersOut spring above (see
-- "LOOK AND FEEL"); only the per-namespace style differs here, since
-- hl.animation() only accepts Hyprland's fixed set of animation leaves.
hl.layer_rule({
	name = "waybar-anim",
	match = { namespace = "^waybar$" },
	animation = "slide",
})

-- The launcher is a fullscreen transparent Quickshell surface that animates its
-- own card in QML, so the compositor must not animate the surface itself.
-- ignore_alpha keeps the blur on the card (alpha 0.72) and off the dim layer
-- behind it (alpha 0.32).
hl.layer_rule({
	name = "launcher-anim",
	match = { namespace = "^launcher$" },
	no_anim = true,
	blur = true,
	ignore_alpha = 0.5,
})

-- El menú de sesión de la barra es otra superficie Quickshell a pantalla
-- completa (~/.config/quickshell/powermenu/shell.qml) que anima su propia
-- tarjeta, así que el compositor tampoco debe animar la superficie. El
-- ignore_alpha es el mismo del lanzador y por el mismo motivo: mantiene el
-- desenfoque bajo el cristal (alfa 0.74) y lo quita del resto de la superficie,
-- que es transparente y sólo está ahí para recoger los clics de fuera.
hl.layer_rule({
	name = "powermenu-anim",
	match = { namespace = "^powermenu$" },
	no_anim = true,
	blur = true,
	ignore_alpha = 0.5,
})

-- El aviso de paquetes pendientes es un disco centrado que anima su propia
-- entrada, así que el compositor no debe animar la superficie. Mismo
-- ignore_alpha que los otros dos, y por lo mismo: mantiene el desenfoque bajo
-- el cristal del disco.
hl.layer_rule({
	name = "updates-anim",
	match = { namespace = "^updates$" },
	no_anim = true,
	blur = true,
	ignore_alpha = 0.5,
})

-- Hyprland-run windowrule
hl.window_rule({
	name = "move-hyprland-run",
	match = { class = "hyprland-run" },

	move = "20 monitor_h-120",
	float = true,
})

-----------------------
---- DOTFILES SYNC ----
-----------------------

-- Pulls github.com/IshimiG/set-up on every Hyprland start so the
-- symlinked configs in ~/.config stay in sync with the git repo,
-- then (re)starts waybar with that synced config.
hl.on("hyprland.start", function()
	hl.exec_cmd("~/.local/bin/dotfiles-sync.sh")
	hl.exec_cmd("pkill waybar; waybar")
	hl.exec_cmd("pkill hyprpaper; hyprpaper")
	-- Cuántos paquetes hay pendientes, en un disco en el centro de la
	-- pantalla. El script espera a que haya red antes de contar y no enseña
	-- nada si no hay ninguno, así que puede lanzarse sin más.
	hl.exec_cmd("~/.config/hypr/scripts/updates-notify.sh")
end)

